    \end{proof}

    We now take an element
    \[D=\eta^\ell \prod_{j=1}^g\ch_1^\HH(f_j)^{a_j} \ch_0^\HH(e_j)^{b_j}\in \widetilde \BD^C\,.\]
Then we have
\begin{equation}
\label{eq: symvirasorooutput}
