&=\sum_{t=1}^g \int_{C^n}\eta^{k+\ell-1}\ch_1^\HH(f_t)\ch_0^\HH(e_t)\prod_{j\in J}\ch_1^\HH(f_j)\ch_0^\HH(e_j)\\
